mapper.select:
SELECT msbd.channel_id, SUM(COALESCE(msbd.send_count, 0)) AS send_count, SUM(COALESCE(msbd.success_count, 0)) AS success_count FROM message_stat_by_degree msbd INNER JOIN channel c ON c.id = msbd.channel_id AND c.is_deleted = 0 WHERE msbd.is_deleted = 0
AND msbd.stat_date >= #{from}
AND msbd.stat_date <= #{to}
AND c.channel_type = #{channel}
GROUP BY msbd.channel_id ORDER BY msbd.channel_id

SELECT latest_customer.stat_date, latest_customer.total_customer_count, latest_customer.normal_customer_count, latest_customer.new_customer_count, latest_customer.dormant_customer_count, latest_customer.sms_consent_count, latest_customer.kakao_consent_count, latest_customer.email_consent_count, latest_customer.joined_customer_count FROM ( SELECT cs.stat_date, cs.total_customer_count, cs.normal_customer_count, cs.new_customer_count, cs.dormant_customer_count, cs.sms_consent_count, cs.kakao_consent_count, cs.email_consent_count, cs.joined_customer_count FROM customer_stat cs WHERE cs.is_deleted = 0
AND cs.stat_date >= #{from}
AND cs.stat_date <= #{to}
ORDER BY cs.stat_date DESC FETCH FIRST 1 ROW ONLY ) latest_customer

SELECT COALESCE(t.title, '템플릿 ' || ts.template_id) AS name, CASE WHEN SUM(COALESCE(ts.click_target_count, 0)) = 0 THEN 0 ELSE ROUND((SUM(COALESCE(ts.click_count, 0)) / SUM(COALESCE(ts.click_target_count, 0))) * 100, 1) END AS click, CASE WHEN SUM(COALESCE(ts.conversion_target_count, 0)) = 0 THEN NULL ELSE ROUND((SUM(COALESCE(ts.conversion_count, 0)) / SUM(COALESCE(ts.conversion_target_count, 0))) * 100, 1) END AS conversion, CASE WHEN COALESCE(t.is_ai_generated, 0) = 1 THEN 'AI 템플릿' ELSE '기본 템플릿' END AS source FROM template_stat ts LEFT JOIN template t ON t.id = ts.template_id AND t.is_deleted = 0 WHERE ts.is_deleted = 0
AND ts.stat_date >= #{from}
AND ts.stat_date <= #{to}
GROUP BY ts.template_id, t.title, t.is_ai_generated ORDER BY CASE WHEN SUM(COALESCE(ts.click_target_count, 0)) = 0 THEN 0 ELSE SUM(COALESCE(ts.click_count, 0)) / SUM(COALESCE(ts.click_target_count, 0)) END DESC, SUM(COALESCE(ts.click_count, 0)) DESC FETCH FIRST 5 ROWS ONLY
